const body = $('Admin API Webhook').first().json.body || {};
const str = (v) => (v === null || v === undefined) ? '' : String(v).trim();
return [{ json: {
  action: str(body.action),
  sessionId: str(body.sessionId),
  startDate: str(body.startDate),          // ISO 8601 з часовою зоною (бекенд адмінпанелі надсилає UTC)
  maxParticipants: body.maxParticipants,
} }];

const cfg = $('Конфіг').first().json;
const rows = (items) => items.map((i) => i.json).filter((j) => j && j.id !== undefined && j.id !== null);
const maxOf = (s) => (Number(s.max_participants) > 0 ? Number(s.max_participants) : Number(cfg.DEFAULT_MAX_PARTICIPANTS));
const shapeSession = (s, count) => {
  const max = maxOf(s);
  return {
    id: s.session_id,
    name: s.session_name || '',
    startDate: s.start_date || null,                         // ISO 8601 UTC
    status: s.status || 'Open',                              // Open / Full / Closed
    maxParticipants: max,
    currentCount: count,                                     // активні (не Cancelled) реєстрації
    availableSeats: Math.max(0, max - count),
    isPast: s.start_date ? new Date(s.start_date).getTime() <= Date.now() : false,
    createdAt: s.createdAt || null,
    updatedAt: s.updatedAt || null,
  };
};
const shapeParticipant = (p) => ({
  id: p.id,
  name: p.name || '',
  phone: p.phone || '',
  keycrmId: p.keycrm_id || '',
  registrationStatus: p.registration_status || '',
  keycrmSync: p.keycrm_sync || '',
  createdAt: p.createdAt || null,
});
const isActive = (p) => p.registration_status !== 'Cancelled';
const fail = (statusCode, code, message, extra = {}) => ({ json: { ok: false, statusCode, body: { error: { code, message, ...extra } } } });
const ok = (statusCode, body) => ({ json: { ok: true, statusCode, body } });
