const req = $('Розбір запиту').first().json;
if (!req.sessionId) return [fail(400, 'SESSION_ID_REQUIRED', 'Не вказано sessionId')];
const s = rows($('DT: сесія (update)').all())[0];
if (!s) return [fail(404, 'SESSION_NOT_FOUND', 'Співбесіду не знайдено')];
const count = rows($input.all()).length;
const start = DateTime.fromISO(req.startDate, { setZone: true });
const max = Number(req.maxParticipants);
if (!req.startDate || !start.isValid) return [fail(400, 'INVALID_START_DATE', 'Некоректна дата або час співбесіди')];
if (!Number.isInteger(max) || max <= 0) return [fail(400, 'INVALID_MAX_PARTICIPANTS', 'Максимальна кількість учасників має бути додатним цілим числом')];
const startIso = start.toUTC().toISO();
const startChanged = new Date(startIso).getTime() !== new Date(s.start_date).getTime();
if (startChanged && start.toMillis() <= Date.now()) return [fail(400, 'START_IN_PAST', 'Не можна перенести співбесіду в минуле')];
if (max < count) return [fail(409, 'CAPACITY_BELOW_REGISTERED', `Не можна зменшити місткість нижче поточної кількості зареєстрованих кандидатів (${count})`, { currentCount: count })];
