const status = s.status === 'Closed' ? 'Closed' : (count >= max ? 'Full' : 'Open');
const row = { session_name: sessionName(startIso), start_date: startIso, max_participants: max, status };
return [{ json: { ok: true, sessionId: s.session_id, row, session: shapeSession({ ...s, ...row }, count) } }];

